  const fadeMaterials = [];

  // ---------------------------------------------------------------
  // BACKDROP PANEL — engineered radial gradient + hairline grid
  // ---------------------------------------------------------------
  const PANEL_W = 3.2;
  const PANEL_H = 2.2;

  const uvN = uv();
  const centered = uvN.sub(vec2(0.5, 0.5));
  const dist = length(centered).mul(1.35);
  const gradT = smoothstep(0.0, 1.0, dist);
  const baseGrad = mix(color('#14141a'), color('#0b0b10'), gradT);

  const pitch = 0.25;
  const gridScale = vec2(PANEL_W / pitch, PANEL_H / pitch);
  const gUv = uvN.mul(gridScale);
  const fx = fract(gUv.x);
  const fy = fract(gUv.y);
  const lineW = 0.06;
  const lineX = smoothstep(0.0, lineW, fx).oneMinus().add(smoothstep(1.0 - lineW, 1.0, fx));
  const lineY = smoothstep(0.0, lineW, fy).oneMinus().add(smoothstep(1.0 - lineW, 1.0, fy));
  const gridMask = lineX.max(lineY).clamp(0.0, 1.0);
  const finalPanelColor = mix(baseGrad, color(colors.paper ?? '#e8ecf2'), gridMask.mul(0.06));

  const panelMaterial = new MeshStandardNodeMaterial({
    roughness: 0.58,
    metalness: 0.08,
    side: DoubleSide,
  });
  panelMaterial.colorNode = finalPanelColor;
  panelMaterial.transparent = true;
  panelMaterial.opacity = 1;

  const panelMesh = new Mesh(new PlaneGeometry(PANEL_W, PANEL_H, 1, 1), panelMaterial);
  panelMesh.position.set(0, 0, 0);
  contentGroup.add(panelMesh);
  fadeMaterials.push({ mat: panelMaterial, target: 1 });

  // hairline border
  const borderMat = new LineBasicMaterial({ color: '#26262f', transparent: true, opacity: 0.9 });
  const borderLine = new LineLoop(
    new BufferGeometry().setFromPoints([
      new THREE.Vector3(-PANEL_W / 2, -PANEL_H / 2, 0.001),
      new THREE.Vector3(PANEL_W / 2, -PANEL_H / 2, 0.001),
      new THREE.Vector3(PANEL_W / 2, PANEL_H / 2, 0.001),
      new THREE.Vector3(-PANEL_W / 2, PANEL_H / 2, 0.001),
    ]),
    borderMat
  );
  contentGroup.add(borderLine);
  fadeMaterials.push({ mat: borderMat, target: 0.9 });

  // ---------------------------------------------------------------
  // GHOST PREVIEW — wireframe watch-card, dial, text bars (breathing)
  // ---------------------------------------------------------------
  const ghostGroup = new Group();
  ghostGroup.position.set(-0.95, 0.05, 0.01);
  contentGroup.add(ghostGroup);

  const ghostLineMat = new LineBasicMaterial({ color: colors.paper ?? '#e8ecf2', transparent: true, opacity: 0.3 });
  const ghostOutline = new LineSegments(
    new EdgesGeometry(new PlaneGeometry(1.1, 1.4)),
    ghostLineMat
  );
  ghostGroup.add(ghostOutline);

  const dialCurve = new EllipseCurve(0, 0.18, 0.275, 0.275, 0, Math.PI * 2, false, 0);
  const dialPoints = dialCurve.getPoints(48).map((p) => new THREE.Vector3(p.x, p.y, 0.002));
  const ghostDialMat = new LineBasicMaterial({ color: colors.paper ?? '#e8ecf2', transparent: true, opacity: 0.3 });
  const ghostDial = new LineLoop(new BufferGeometry().setFromPoints(dialPoints), ghostDialMat);
  ghostGroup.add(ghostDial);

  const ghostBarMat1 = new MeshBasicNodeMaterial({ color: colors.paper ?? '#e8ecf2', transparent: true, opacity: 0.22 });
  const ghostBar1 = new Mesh(new PlaneGeometry(0.7, 0.06), ghostBarMat1);
  ghostBar1.position.set(0, -0.38, 0.002);
  ghostGroup.add(ghostBar1);

  const ghostBarMat2 = new MeshBasicNodeMaterial({ color: colors.paper ?? '#e8ecf2', transparent: true, opacity: 0.22 });
  const ghostBar2 = new Mesh(new PlaneGeometry(0.7, 0.06), ghostBarMat2);
  ghostBar2.position.set(0, -0.52, 0.002);
  ghostGroup.add(ghostBar2);

  const ghostMats = [
    { mat: ghostLineMat, base: 0.3 },
    { mat: ghostDialMat, base: 0.3 },
    { mat: ghostBarMat1, base: 0.22 },
    { mat: ghostBarMat2, base: 0.22 },
  ];

  const breatheState = { t: 0.24 / 0.3 };
  const breatheTl = gsap.timeline({ repeat: -1, yoyo: true, delay: 0.55 });
  breatheTl.to(breatheState, {
    t: 0.34 / 0.3,
