  copyGroup.position.set(0.15, 0.42, 0.01);
  contentGroup.add(copyGroup);

  const headline = ctx.fontAtlas.createText(headlineText, {
    fontSize: 34,
    color: colors.paper ?? '#e8ecf2',
    align: 'left',
    maxWidthPx: 380,
  });
  headline.position.set(0, 0, 0);
  copyGroup.add(headline);

  const body = ctx.fontAtlas.createText(bodyText, {
    fontSize: 13,
    color: colors.paper ?? '#e8ecf2',
    align: 'left',
    maxWidthPx: 380,
  });
  body.position.set(0, -0.36, 0);
  copyGroup.add(body);

  // ---------------------------------------------------------------
  // ACCENT CTA — extruded 3D button with vertical gradient + emissive edge
  // ---------------------------------------------------------------
  const ctaGroup = new Group();
  ctaGroup.position.set(0.15, -0.62, 0.02);
  contentGroup.add(ctaGroup);

  const ctaUv = uv();
  const ctaGrad = mix(color('#ff4450'), color('#c1121f'), ctaUv.y);

  const ctaMaterial = new MeshStandardNodeMaterial({
    roughness: 0.5,
    metalness: 0.4,
    clearcoat: 0.15,
    transparent: true,
  });
  ctaMaterial.colorNode = ctaGrad;
  ctaMaterial.emissive = new THREE.Color(colors.accent ?? '#ff2a38');
  ctaMaterial.emissiveIntensity = 1.5;
  ctaMaterial.opacity = 1;

  const ctaMesh = new Mesh(new BoxGeometry(1.5, 0.36, 0.08), ctaMaterial);
  ctaGroup.add(ctaMesh);
  fadeMaterials.push({ mat: ctaMaterial, target: 1 });

  const ctaLabel = ctx.fontAtlas.createText(ctaText, {
    fontSize: 13,
    color: colors.ink ?? '#16161d',
    align: 'center',
    letterSpacingPx: 1,
  });
  ctaLabel.position.set(0, 0, 0.05);
  ctaGroup.add(ctaLabel);

  // ---------------------------------------------------------------
  // LOCAL LIGHTS (node-local rim/accent, within intensity caps)
  // ---------------------------------------------------------------
  const accentLight = new PointLight(colors.accent ?? '#ff2a38', 0.5, 3.5, 2);
  accentLight.position.set(0.5, -0.6, 0.8);
  contentGroup.add(accentLight);

  const grazeLight = new DirectionalLight('#ffffff', 0.4);
  grazeLight.position.set(-1.5, 1.2, 1.5);
  contentGroup.add(grazeLight);

  // ---------------------------------------------------------------
  // MOUNT ANIMATION — fade-up
  // ---------------------------------------------------------------
  const mountAlpha = { v: 0 };
  contentGroup.position.y = 0.2;

  fadeMaterials.forEach(({ mat }) => {
    mat.transparent = true;
  });

  const mountTl = gsap.timeline();
  mountTl.to(contentGroup.position, {
    y: 0,
    duration: 0.5,
    ease: 'power2.out',
  }, 0);
  mountTl.to(mountAlpha, {
    v: 1,
    duration: 0.5,
    ease: 'power2.out',
    onUpdate: () => {
      fadeMaterials.forEach(({ mat, target }) => {
        mat.opacity = target * mountAlpha.v;
      });
      ghostMats.forEach(({ mat, base }) => {
        mat.opacity = base * breatheState.t * mountAlpha.v;
      });
    },
  }, 0);
  tweens.push(mountTl);

