  // INTERACTION — accent CTA press + hover + navigate
  // ---------------------------------------------------------------
  function isCtaTarget(e) {
    const obj = e?.object;
    if (!obj) return true;
    return obj === ctaMesh || obj === ctaLabel || ctaGroup.children.includes(obj);
  }

  let pressTween = null;
  let tiltTween = null;

  root.userData.handlers = {
    onPointerEnter: (e) => {
      if (!isCtaTarget(e)) return;
      if (tiltTween) tiltTween.kill();
      tiltTween = gsap.to(ctaGroup.rotation, {
        x: THREE.MathUtils.degToRad(-4),
        duration: 0.3,
        ease: 'power2.out',
      });
